use super::*;

/// Where this month's spare money goes.
///
/// The allocations print IN ORDER, because the order IS the recommendation — and each carries its
/// own reason, so a reader can disagree with the rule rather than only with the number.
pub fn render_priority(p: &priority::Priority, discretionary: i64, read_notes: &[String]) -> String {
    let mut out = String::new();
    let m = |x: i64| crate::money::format_minor(x);
    out.push_str(&format!(
        "{} a month is genuinely spare — the WORST month's net, not a good one\n  (discretionary spending taken as {} a month)\n\n",
        m(p.available.minor),
        m(discretionary)
    ));
    for al in &p.allocations {
        out.push_str(&format!("  {:<9}{:>12}   {}\n", al.kind.label(), m(al.amount.minor), al.label));
        out.push_str(&format!("            {}\n", al.reason));
    }
    out.push_str(&format!("\n  total this month  {}\n", m(priority::total_commitment(p).minor)));
    if p.lump_available.minor > 0 {
        // A ONE-OFF, kept separate from the monthly figure so the two are not added by accident.
        out.push_str(&format!("  liquid above the buffer, available as a ONE-OFF: {}\n", m(p.lump_available.minor)));
    }
    if !p.order.is_empty() {
        out.push_str(&format!("\n  the order after this one: {}\n", p.order.join(" → ")));
    }
    if !p.warnings.is_empty() || !read_notes.is_empty() {
        out.push_str("\nWhat this is standing on:\n");
        for w in &p.warnings {
            out.push_str(&format!("  · {w}\n"));
        }
        for n in read_notes {
            out.push_str(&format!("  · {n}\n"));
        }
    }
    out
}
